export const getAddFriendUrl = () => {




  return `/api/friends`
}

/**
 * @summary Send a friend request or add a friend
 */
export const addFriend = async (addFriendBody: AddFriendBody, options?: RequestInit): Promise<Friendship> => {

  return customFetch<Friendship>(getAddFriendUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(addFriendBody)
  }
);}





export const getAddFriendMutationOptions = <TError = ErrorType<ErrorResponse>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof addFriend>>, TError,{data: BodyType<AddFriendBody>}, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof addFriend>>, TError,{data: BodyType<AddFriendBody>}, TContext> => {

const mutationKey = ['addFriend'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof addFriend>>, {data: BodyType<AddFriendBody>}> = (props) => {
          const {data} = props ?? {};

          return  addFriend(data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type AddFriendMutationResult = NonNullable<Awaited<ReturnType<typeof addFriend>>>
    export type AddFriendMutationBody = BodyType<AddFriendBody>
    export type AddFriendMutationError = ErrorType<ErrorResponse>

    /**
 * @summary Send a friend request or add a friend
 */
export const useAddFriend = <TError = ErrorType<ErrorResponse>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof addFriend>>, TError,{data: BodyType<AddFriendBody>}, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof addFriend>>,
        TError,
        {data: BodyType<AddFriendBody>},
        TContext
      > => {
      return useMutation(getAddFriendMutationOptions(options));
    }

